"""RPC Book Two, Title Seven (Arts. 203-245): crimes committed by public officers."""

RA3019 = {'t': 'Anti-Graft and Corrupt Practices Act (RA 3019)', 's': 'Separately punishes corrupt practices of public officers (e.g., Sec. 3(e) undue injury or unwarranted benefits); a single act may violate both RA 3019 and the Code.', 'u': ''}
RA7080 = {'t': 'Plunder (RA 7080, as amended by RA 7659)', 's': 'Amassing ill-gotten wealth of at least ₱50 million through a combination or series of overt criminal acts (including malversation and bribery).', 'u': ''}


def add(n):
    n(203, 'Who are public officers for Book Two: any person who, by direct provision of law, popular election or appointment by competent authority, takes part in the performance of public functions in the Government, or performs public duties as an employee, agent or subordinate official, of any rank or class.',
      t=['The definition is broad: what matters is participation in public functions, not rank or permanence of the position.'],
      d=[{'n': 'Javier v. Sandiganbayan', 'c': 'G.R. Nos. 147026-27, September 11, 2009', 'h': 'A private-sector representative appointed to the governing board of a government agency was a public officer for purposes of malversation and the anti-graft law: she performed public functions by appointment.', 'r': 'Breadth of “public officer”.'}],
      chk=['direct provision of the law, popular election or appointment'])
    n(204, 'Knowingly rendering an unjust judgment: a judge renders a judgment that is unjust (contrary to law or unsupported by evidence), knowing it to be unjust.',
      k=['Offender is a judge.', 'He renders a judgment in a case submitted to him.', 'The judgment is unjust.', 'He knows it is unjust.'],
      t=['A judge cannot be charged with knowingly rendering an unjust judgment while the judgment is pending review; there must first be a final declaration by a competent court that it is unjust (In re: Joaquin T. Borromeo).'],
      d=[{'n': 'In re: Joaquin T. Borromeo', 'c': 'A.M. No. 93-7-696-0, February 21, 1995', 'h': 'A litigant who repeatedly filed criminal complaints against judges for “unjust” rulings was held in contempt; the proper remedy against an erroneous judgment is appeal or other judicial review, and a charge of knowingly rendering an unjust judgment requires a prior final finding that the judgment is unjust.', 'r': 'The prerequisite for Arts. 204-206 charges.'}],
      chk=['knowingly render an unjust judgment'])
    n(205, 'Unjust judgment through inexcusable negligence or ignorance: a judge who renders a manifestly unjust judgment by reason of inexcusable negligence or ignorance.', chk=['inexcusable negligence or ignorance'])
    n(206, 'Unjust interlocutory order: a judge who knowingly — or through inexcusable negligence or ignorance — renders a manifestly unjust interlocutory order or decree.', chk=['interlocutory order'])
    n(207, 'Malicious delay in the administration of justice by a judge.', t=['Delay alone is not enough; malice — a deliberate intent to prejudice a party — must be shown.'], chk=['malicious delay'])
    n(208, 'Prosecution of offenses; negligence and tolerance: a public officer or officer of the law who, in dereliction of duty, maliciously refrains from instituting prosecution for violations of law, or tolerates their commission.',
      t=['The offender must have the duty to prosecute or move for prosecution (prosecutors, police officers, barangay officials with police functions).', 'If the officer refrains in exchange for a gift, see bribery (Arts. 210, 211-A).'],
      chk=['maliciously refrain from instituting prosecution'])
    n(209, 'Betrayal of trust by an attorney (or any person authorized to represent or assist a party): causing damage to a client by malicious breach of professional duty or inexcusable negligence or ignorance; revealing the client’s secrets learned in professional capacity; or, having undertaken a client’s defense, undertaking the defense of the opposing party in the same case without the first client’s consent.',
      t=['Criminal liability is in addition to administrative (disciplinary) action under the CPRA.', 'Revealing secrets does not require damage; the first mode does.'],
      chk=['In addition to the proper administrative action', 'opposing party'])
    n(210, 'Direct bribery (as amended by BP 871): a public officer who agrees to perform an act constituting a crime, or an act not constituting a crime, or refrains from doing something that is his official duty, in consideration of an offer, promise, gift or present received personally or through another. Applies also to assessors, arbitrators, appraisers, claim commissioners, experts and others performing public duties.',
      k=['Offender is a public officer (or one performing public duties).', 'He accepts an offer or promise or receives a gift or present, personally or through another.', 'In consideration of: (1) committing a crime, (2) an unjust act not a crime, or (3) refraining from an official duty.', 'The act relates to the exercise of his functions.'],
      t=['In the first mode, the crime agreed upon is punished separately if committed.', 'The mere agreement in consideration of a gift received completes the first and third modes; for the second, the penalty depends on whether the act was executed.', 'The giver is liable for corruption of public officials (Art. 212).'],
      i=[RA3019], chk=['agree to perform an act constituting a crime', 'refrain from doing something which it was his official duty to do'])
    n(211, 'Indirect bribery (as amended by BP 871): a public officer who accepts gifts offered to him by reason of his office.',
      k=['Offender is a public officer.', 'He accepts gifts.', 'The gifts are offered by reason of his office.'],
      t=['No agreement to do or not do an act is needed — that is the difference from direct bribery.', 'Acceptance is essential: a gift refused or immediately returned is not indirect bribery.', 'Indirect bribery cannot be committed in the attempted or frustrated stage.'],
      chk=['accept gifts offered to him by reason of his office'])
    n('211-a', 'Qualified bribery (added by RA 7659): a public officer entrusted with law enforcement who refrains from arresting or prosecuting an offender who committed a crime punishable by reclusion perpetua or death, in consideration of an offer, promise, gift or present, suffers the penalty for the offense not prosecuted; if he himself asked or demanded the gift, death (now reclusion perpetua without parole under RA 9346).',
      chk=['entrusted with law enforcement', 'reclusion perpetua and/or death'])
    n(212, 'Corruption of public officials: the person who makes the offers or promises or gives the gifts or presents in Arts. 210, 211 and 211-A suffers the same penalties as the officer corrupted, except disqualification and suspension.',
      t=['If the officer rejects the offer or promise, the giver may still be liable for attempted corruption of a public official.', 'Givers of bribes who testify against the public officer may be granted immunity under PD 749.'],
      chk=['made the offers or promises or given the gifts or presents'])
    n(213, 'Frauds against the public treasury and illegal exactions: a public officer who, in his official capacity, enters into an agreement or uses another scheme to defraud the Government in dealings concerning public funds or property; and an officer in charge of collecting taxes or fees who demands sums different from or larger than those authorized, fails to issue receipts, or collects in kind without authority.',
      t=['Illegal exaction by demanding a larger amount is consummated by the demand; actual collection is not required.', 'Mere demand of an amount larger than authorized may also violate RA 3019.'],
      chk=['defraud the Government'])
    n(214, 'Other frauds: a public officer who, taking advantage of his position, commits any of the frauds in Chapter Six, Title Ten (estafa and other deceits) suffers, in addition, temporary special to perpetual special disqualification.', t=['The estafa is still punished under Arts. 315-318; Art. 214 adds the disqualification.'], chk=['perpetual special disqualification'])
    n(215, 'Prohibited transactions: an appointive public officer who, during his incumbency, directly or indirectly becomes interested in a transaction of exchange or speculation within the territory subject to his jurisdiction.', t=['Elective officials are not covered by Art. 215; see RA 6713 and RA 3019, Sec. 3(h).'], chk=['appointive public officer'])
    n(216, 'Possession of prohibited interest: a public officer who, directly or indirectly, becomes interested in any contract or business in which he intervenes in his official capacity; also experts, arbitrators, guardians and executors as to property entrusted to them.', t=['Actual fraud is not required; the conflict of interest itself is punished.'], chk=['interested in any contract or business'])
    n(217, 'Malversation of public funds or property: a public officer accountable for public funds or property by reason of his duties who appropriates, takes or misappropriates them, consents to another’s taking, or through abandonment or negligence permits another to take them. The penalty depends on the amount (as adjusted by RA 10951). Failure to have the funds duly forthcoming upon demand by a duly authorized officer is prima facie evidence of personal use.',
      k=['Offender is a public officer (or a private person under Art. 222, or one in conspiracy with the officer).', 'He has custody or control of funds or property by reason of his office.', 'They are public funds or property for which he is accountable.', 'He appropriated, took, misappropriated, or consented to or, through abandonment or negligence, permitted their taking.'],
      t=['Malversation may be committed intentionally or by negligence; the penalty is the same and an information for intentional malversation can support a conviction for malversation through negligence.', 'Demand is not an element; it only raises the presumption.', 'Restitution does not extinguish criminal liability; it may only mitigate.', 'Private individuals who conspire with the accountable officer are liable as co-principals.'],
      i=[RA7080], chk=['accountable for public funds or property', 'through abandonment or negligence', 'prima facie evidence'])
    n(218, 'Failure of an accountable officer to render accounts: an accountable officer, in service or already separated, who fails to render his accounts to the Commission on Audit or a provincial auditor within two months after they should be rendered.', t=['Misappropriation need not be shown.'], chk=['Commission on Audit'])
    n(219, 'Failure to render accounts before leaving the country: a public officer who unlawfully leaves or attempts to leave the Philippines without securing a certificate from the Commission on Audit that his accounts are fully settled.', chk=['without securing a certificate'])
    n(220, 'Illegal use of public funds or property (technical malversation): a public officer who applies public funds or property under his administration to a public use other than that for which they were appropriated by law or ordinance. Heavier if damage or embarrassment to the public service results.',
      k=['Public funds or property under his administration.', 'Appropriated by law or ordinance for a specific purpose.', 'Applied to another public use.'],
      t=['There is no personal gain: the funds go to a public purpose, just not the one appropriated. Good faith or that the new use was beneficial is no defense.'],
      d=[{'n': 'Ysidoro v. People', 'c': 'G.R. No. 192330, November 14, 2012', 'h': 'A mayor who diverted construction materials appropriated for a calamity-victims housing program to a different program was liable for technical malversation; criminal intent is not required, since the law punishes the unauthorized application itself.', 'r': 'Technical malversation is malum prohibitum in character.'}],
      chk=['other than that for which such fund or property were appropriated'])
    n(221, 'Failure to make delivery of public funds or property: a public officer obliged to make a payment from Government funds in his possession who fails to do so, or who refuses to deliver property in his custody when ordered by competent authority.', chk=['fail to make such payment'])
    n(222, 'The provisions on malversation apply to private individuals who have charge of public funds or property in any capacity, and to administrators or depositaries of funds or property attached, seized or deposited by public authority, even if owned by private individuals.',
      t=['A private individual who, in conspiracy with an accountable officer, malversed funds is also liable (as a co-principal, not under Art. 222).'], chk=['private individuals'])
    n(223, 'Conniving with or consenting to evasion: a public officer who consents to the escape of a prisoner in his custody or charge; the penalty depends on whether the prisoner was a convict or a detention prisoner.', t=['The prisoner need not actually be convicted by final judgment for this article; “prisoner” includes detention prisoners.'], chk=['consent to the escape of a prisoner'])
    n(224, 'Evasion through negligence: a public officer charged with the conveyance or custody of a prisoner who allows the escape through negligence.', t=['The negligence must be definite and positive — not a mere lapse, such as when the escape was by force the officer could not prevent.'], chk=['negligence of the officer'])
    n(225, 'Escape of a prisoner in the custody of a private person: a private person to whom the conveyance or custody of a prisoner is entrusted who connives with, consents to, or through negligence allows the escape.', chk=['private person'])
    n(226, 'Removal, concealment or destruction of documents: a public officer who removes, destroys or conceals documents or papers officially entrusted to him, causing damage to a third party or the public interest.', t=['Removal must be for an illicit purpose (e.g., to tamper with or profit from the document).'], chk=['remove, destroy or conceal documents'])
    n(227, 'Officer breaking seal: a public officer charged with custody of papers or property sealed by proper authority who breaks the seals or permits them to be broken.', t=['Damage is not required.'], chk=['break the seals'])
    n(228, 'Opening of closed documents: a public officer, not covered by Art. 227, who opens or permits to be opened, without proper authority, closed papers, documents or objects entrusted to his custody.', chk=['without proper authority'])
    n(229, 'Revelation of secrets by an officer: revealing secrets known to him by reason of his office, or wrongfully delivering papers or copies of papers he should not publish; heavier if serious damage to the public interest results.', chk=['reveal any secret known to him by reason of his official capacity'])
    n(230, 'Public officer revealing secrets of a private individual that he learned by reason of his office.', chk=['secrets of any private individual'])
    n(231, 'Open disobedience: a judicial or executive officer who openly refuses to execute the judgment, decision or order of a superior authority made within its jurisdiction and with the legal formalities.', chk=['openly refuse'])
    n(232, 'Disobedience to an order of a superior that the inferior officer suspended: having suspended the order for any reason, the officer disobeys after the superior disapproves the suspension.', chk=['disapproved the suspension'])
    n(233, 'Refusal of assistance: a public officer who, upon demand from competent authority, fails to lend his cooperation toward the administration of justice or another public service; the penalty is heavier if the failure results in serious damage to the public interest or to a third party.', chk=['fail to lend his cooperation', 'serious damage to the public interest'])
    n(234, 'Refusal to discharge elective office: a person elected by popular election who refuses, without legal motive, to be sworn in or to discharge the duties of the office.', chk=['refuse without legal motive'])
    n(235, 'Maltreatment of prisoners: a public officer or employee who overdoes himself in the correction or handling of a prisoner or detention prisoner under his charge by imposing punishments not authorized by regulations, or by inflicting them in a cruel and humiliating manner; heavier if done to extort a confession or information.',
      t=['The prisoner must be under the officer’s charge; otherwise the crime is physical injuries.', 'The Anti-Torture Act (RA 9745) separately punishes torture and is not absorbed by this article.'],
      chk=['overdo himself in the correction or handling of a prisoner'])
    n(236, 'Anticipation of duties: assuming the duties and powers of a public office without first taking the oath or giving the required bond.', chk=['without first being sworn in or having given the bond'])
    n(237, 'Prolonging performance of duties: a public officer who continues to exercise the duties of his office beyond the period provided by law, regulation or special provision.', chk=['beyond the period provided by law'])
    n(238, 'Abandonment of office: a public officer who abandons his office before acceptance of his resignation, to the detriment of the public service; heavier if the purpose is to evade the discharge of duties of preventing, prosecuting or punishing crimes against national security.', chk=['before the acceptance of his resignation'])
    n(239, 'Usurpation of legislative powers: a public officer who encroaches on legislative powers by making general rules or regulations beyond his authority, or attempts to repeal a law or suspend its execution.', chk=['legislative powers'])
    n(240, 'Usurpation of executive functions: a judge who assumes a power pertaining to the executive authorities or obstructs them in the lawful exercise of their powers.', chk=['pertaining to the executive authorities'])
    n(241, 'Usurpation of judicial functions: an officer of the executive branch who assumes judicial powers or obstructs the execution of an order or decision of a judge within his jurisdiction.', chk=['assume judicial powers'])
    n(242, 'Disobeying a request for disqualification: a public officer who, before a question of jurisdiction is decided, continues the proceeding after having been lawfully required to refrain.', chk=['continue any proceeding'])
    n(243, 'Orders or requests by executive officers to a judicial authority: an executive officer who addresses an order or suggestion to a judicial authority concerning a case within the latter’s exclusive jurisdiction.', chk=['order or suggestion'])
    n(244, 'Unlawful appointments: a public officer who knowingly nominates or appoints to a public office a person lacking the legal qualifications.', chk=['lacking the legal qualifications'])
    n(245, 'Abuses against chastity: (1) a public officer who solicits or makes immoral or indecent advances to a woman interested in a matter pending before him for decision or report; (2) a warden or officer in charge of prisoners who solicits or makes such advances to a woman under his custody; (3) the same advances to the wife, daughter, sister or relative within the same degree by affinity of a person in his custody.',
      t=['Mere solicitation consummates the crime; the woman need not yield.', 'If the advances are accompanied by acts, other crimes (acts of lasciviousness, rape, sexual harassment under RA 7877 or RA 11313) may be committed.'],
      chk=['immoral or indecent advances'])
